            new[] { "tutorial.skip", "튜토리얼 건너뛰기", "Skip the tutorial", "チュートリアルをスキップ" },
            new[] { "tutorial.eyebrow", "튜토리얼", "Tutorial", "チュートリアル" },
            new[] { "tutorial.skipTitle", "튜토리얼을 건너뛸까요?", "Skip the tutorial?", "チュートリアルをスキップしますか？" },
            new[] { "tutorial.skipBody", "건너뛰면 다시 표시되지 않아요.", "It won't be shown again.", "スキップすると、再び表示されません。" },
            new[] { "tutorial.skipStay", "계속하기", "Keep going", "続ける" },
            new[] { "tutorial.skipLeave", "건너뛰기", "Skip", "スキップ" },
            new[] { "tutorial.doneEyebrow", "튜토리얼 완료", "Tutorial complete", "チュートリアル完了" },
            new[] { "tutorial.doneBody", "이제 AI 대전과 온라인 대전에 도전해 보세요!", "Now take on the AI and players online!", "AI対戦とオンライン対戦に挑戦してみましょう！" },
            new[] { "tutorial.start", "시작하기", "Let's go", "はじめる" },

            // ---- the rules popup (RulesPopup): each page's title, then its items, a label (.k) and a line (.t) ----
            new[] { "rules.basics.title", "기본", "Basics", "基本" },
            new[] { "rules.basics.1.k", "목표", "Goal", "目標" },
            new[] { "rules.basics.1.t", "바둑알을 튕겨 하우스 중앙에 상대보다 가까이 보내는 게임이에요. 선후공을 정한 뒤 {ends}엔드를 겨루고, 점수 합계가 높은 쪽이 이겨요.", "Flick your stones closer to the centre of the house than your opponent's. After deciding who goes first, you play {ends:plural:{} end|{} ends}, and the higher total score wins.", "碁石をはじいて、相手よりハウスの中心に近づけるゲームです。先攻・後攻を決めたあと{ends}エンド戦い、合計得点が高いほうの勝ちです。" },
            new[] { "rules.basics.2.k", "시트 설명", "The sheet", "シートの説明" },
            new[] { "rules.basics.3.k", "발사 지점", "Launch spot", "発射位置" },
            new[] { "rules.basics.3.t", "모든 알은 시트 아래쪽 가운데에서 던져요.", "Every stone is thrown from the middle at the bottom of the sheet.", "すべての石はシートの下の中央から投げます。" },
            new[] { "rules.basics.4.k", "최소 라인", "Min line", "最小ライン" },
            new[] { "rules.basics.4.t", "던진 알은 이 선을 완전히 넘어야 해요. 넘지 못하면 무효가 되어 사라져요.", "A thrown stone has to get all the way past this line; one that doesn't is void and removed.", "投げた石はこの線を完全に越える必要があります。越えなければ無効になって取り除かれます。" },
            new[] { "rules.basics.5.k", "하우스", "House", "ハウス" },
            new[] { "rules.basics.5.t", "위쪽의 둥근 과녁이에요. 점수는 하우스에 걸친 알로 계산해요.", "The rings at the top. Points are counted from the stones touching the house.", "上のほうにある円の的です。得点はハウスにかかっている石で計算します。" },
            new[] { "rules.basics.6.k", "측벽", "Side walls", "サイドの壁" },
            new[] { "rules.basics.6.t", "양옆 벽에 튕겨도 돼요. 아웃 라인 옆 벽은 튕기지 않고 알을 받아내요.", "Stones may bounce off the side walls; the walls beside the out line soak them up instead.", "左右の壁で跳ね返らせてもOKです。アウトライン横の壁は跳ね返らずに石を受け止めます。" },
            new[] { "rules.basics.7.k", "아웃 라인", "Out line", "アウトライン" },
            new[] { "rules.basics.7.t", "하우스 뒤의 선이에요. 완전히 넘어간 알은 아웃되어 사라져요. 밀려난 알도 마찬가지예요.", "The line behind the house. Any stone all the way past it is out and removed, even one knocked there.", "ハウスの後ろの線です。完全に越えた石はアウトになって取り除かれます。はじき出された石も同じです。" },
            new[] { "rules.order.title", "선후공 정하기", "Turn Order", "先攻・後攻決め" },
            new[] { "rules.order.target", "표적", "Target", "的" },
            new[] { "rules.order.1.k", "표적을 향해 던지기", "Throw at the target", "的を狙って投げる" },
            new[] { "rules.order.1.t", "경기를 시작하기 전에 첫 엔드의 선후공을 정해요. 시트 어딘가에 표적이 놓이고, 두 사람이 동시에 한 알씩 표적을 향해 던져요. 상대 알은 반투명하게 보이고 서로 부딪히지 않아요. 한 기기에서 둘이 할 때는 차례로 던져요.", "Before the match, the order for the first end is decided. A target is placed somewhere on the sheet and both players throw one stone at it at the same time. The other's stone shows see-through, and the two never meet. Two players on one device take turns.", "試合の前に、最初のエンドの先攻・後攻を決めます。シートのどこかに的が置かれ、二人が同時に1個ずつ的を狙って投げます。相手の石は半透明で、お互いにぶつかりません。1台で2人のときは順番に投げます。" },
            new[] { "rules.order.2.k", "가까운 쪽이 후공", "Closer goes second", "近いほうが後攻" },
            new[] { "rules.order.2.t", "표적 중심에 더 가까이 세운 쪽이 후공이 돼요. 후공은 엔드의 마지막 알을 던지는 유리한 쪽이에요.", "Whoever stops closer to the target's centre goes second, with the advantage of throwing the end's last stone.", "的の中心に近く止めたほうが後攻になります。後攻はエンドの最後の石を投げる有利な側です。" },
            new[] { "rules.order.3.k", "기록이 없거나 같을 때", "No record, or level", "記録なし・同じとき" },
            new[] { "rules.order.3.t", "최소 라인을 넘지 못하거나 아웃된 알은 기록이 없어요. 둘의 기록이 같으면 무작위로 정해요.", "A stone short of the min line or out has no record. If the two records are level, it's decided at random.", "最小ラインを越えない石やアウトの石は記録なしです。二人の記録が同じならランダムで決めます。" },
            new[] { "rules.end.title", "엔드 진행", "Playing an End", "エンドの進め方" },
            new[] { "rules.end.1.k", "차례", "Turns", "順番" },
            new[] { "rules.end.1.t", "•<indent=1em>엔드가 시작되면 선공은 하우스 앞에 보너스 가드 알 하나를 두고 시작해요.</indent>\n•<indent=1em>선공부터 흑과 백이 한 알씩 번갈아 {shots}알씩 던지고, 마지막 알은 후공이 던져요.</indent>\n•<indent=1em>차례마다 {seconds}초 안에 던져야 해요. 최소 라인 위 심지가 다 타면 그 알을 잃어요.</indent>", "•<indent=1em>Each end starts with a bonus guard stone in front of the house for the side going first.</indent>\n•<indent=1em>Starting with that side, Black and White throw one stone at a time, {shots:plural:{} stone|{} stones} each; the side going second throws the last one.</indent>\n•<indent=1em>You have {seconds} seconds a turn. When the fuse over the min line burns out, you lose that stone.</indent>", "•<indent=1em>エンドが始まると、先攻はハウスの前にボーナスガードの石を1個置いてスタートします。</indent>\n•<indent=1em>先攻から黒と白が1個ずつ交互に{shots}個ずつ投げ、最後の石は後攻が投げます。</indent>\n•<indent=1em>毎回{seconds}秒以内に投げる必要があります。最小ラインの上の導火線が燃え尽きるとその石を失います。</indent>" },
            new[] { "rules.end.2.k", "점수", "Scoring", "得点" },
            new[] { "rules.end.2.t", "•<indent=1em>하우스에 걸친 알 가운데 중앙에 가장 가까운 알을 가진 쪽만 점수를 얻어요.</indent>\n•<indent=1em>점수는 상대의 가장 가까운 알보다 중앙에 가까운 내 알 개수예요.</indent>\n•<indent=1em>하우스가 비었거나 가장 가까운 알이 같은 거리면 아무도 점수를 얻지 못해요(블랭크 엔드).</indent>", "•<indent=1em>Of the stones touching the house, only the side with the one closest to the centre scores.</indent>\n•<indent=1em>It scores a point for each of its stones closer than the opponent's closest.</indent>\n•<indent=1em>If the house is empty or the closest stones are level, nobody scores (a blank end).</indent>", "•<indent=1em>ハウスにかかっている石のうち、中心に一番近い石を持つほうだけが得点します。</indent>\n•<indent=1em>得点は、相手の一番近い石より中心に近い自分の石の数です。</indent>\n•<indent=1em>ハウスに石がないか、一番近い石が同じ距離なら、どちらも得点しません（ブランクエンド）。</indent>" },
            new[] { "rules.end.3.k", "다음 엔드와 승패", "Next end, and the result", "次のエンドと勝敗" },
            new[] { "rules.end.3.t", "•<indent=1em>점수를 낸 쪽이 다음 엔드의 선공이 돼요. 블랭크 엔드면 후공이 상대에게 넘어가요.</indent>\n•<indent=1em>마지막 엔드까지 점수 합계가 높은 쪽이 이겨요.</indent>\n•<indent=1em>합계가 같으면 연장 1엔드를 하고, 그래도 같으면 무승부예요.</indent>", "•<indent=1em>The side that scored goes first in the next end. After a blank end, going second passes to the other side.</indent>\n•<indent=1em>The higher total after the last end wins.</indent>\n•<indent=1em>Level, one extra end is played; if it is still level, it's a draw.</indent>", "•<indent=1em>得点したほうが次のエンドの先攻になります。ブランクエンドなら後攻が相手に移ります。</indent>\n•<indent=1em>最後のエンドまでの合計得点が高いほうの勝ちです。</indent>\n•<indent=1em>同点なら延長1エンドを行い、それでも同点なら引き分けです。</indent>" },
            new[] { "rules.controls.title", "조작법", "Controls", "操作方法" },
            new[] { "rules.controls.1.k", "방향", "Direction", "方向" },
            new[] { "rules.controls.1.t", "최소 라인 아래, 알 왼쪽을 좌우로 드래그해요.", "Below the min line, drag left or right on the left of the stone.", "最小ラインより下で、石の左側を左右にドラッグします。" },
            new[] { "rules.controls.2.k", "세기", "Power", "強さ" },
            new[] { "rules.controls.2.t", "알 오른쪽을 위나 아래로 드래그해요. 길게 당길수록 세져요.", "Drag up or down on the right of the stone. The longer the pull, the harder the throw.", "石の右側を上下にドラッグします。長く引くほど強くなります。" },
            new[] { "rules.controls.3.k", "던지기", "Throw", "投げる" },
            new[] { "rules.controls.3.t", "세기를 정한 손가락을 떼면 날아가요.", "Let go of the power finger to throw.", "強さを決めた指を離すと飛んでいきます。" },
            new[] { "rules.controls.4.k", "바로 조준", "Quick aim", "すぐ狙う" },
            new[] { "rules.controls.4.t", "최소 라인 위를 터치하면 그곳을 조준해요. 드래그하면 조준이 따라와요.", "Touch above the min line to aim right there. Drag and the aim follows.", "最小ラインより上をタッチすると、そこを狙います。ドラッグすると狙いがついてきます。" },
            new[] { "rules.controls.5.k", "취소", "Cancel", "キャンセル" },
            new[] { "rules.controls.5.t", "당기던 손가락을 알 왼쪽으로 옮기면 던지지 않아요.", "Move the pulling finger to the left of the stone and it won't throw.", "引いている指を石の左側に動かすと投げません。" },
            new[] { "rules.items.title", "아이템 모드", "Item Mode", "アイテムモード" },
            new[] { "rules.items.1.k", "아이템 획득", "Getting items", "アイテム獲得" },
            new[] { "rules.items.1.t", "시트 위의 내 색 구슬에 내 알이 닿으면 아이템을 얻어요. 무엇이 들었는지는 얻을 때 알 수 있어요. 상대 알이 닿으면 구슬이 깨져요.", "When one of your stones touches an orb of your colour, you get an item; you find out which as you get it. An opponent's stone breaks it.", "シートの上の自分の色の玉に自分の石が触れるとアイテムを得ます。中身は得たときに分かります。相手の石が触れると玉は割れます。" },
            new[] { "rules.items.2.k", "아이템 사용", "Using items", "アイテム使用" },
            new[] { "rules.items.2.t", "아이템은 2개까지 가질 수 있어요. 내 차례에 아이템 칸을 누르면 던질 알에 바로 적용돼요. 한 차례에 하나만 쓸 수 있어요.", "You can hold two. On your turn, tap one to put it on the stone you're about to throw, one a turn.", "アイテムは2個まで持てます。自分の番にアイテム欄をタップすると、投げる石にすぐ使われます。1回に1個だけです。" },
            new[] { "rules.items.3.k", "아이템 리스폰", "Item respawn", "アイテムのリスポーン" },
            new[] { "rules.items.3.t", "먹거나 깨진 구슬은 양쪽이 한 번씩 던지고 나면 다른 곳에 다시 생겨요. 엔드가 바뀌면 구슬이 모두 새 자리에 놓여요.", "Orbs taken or broken turn up somewhere else once both sides have thrown; each new end puts them all out afresh.", "取った玉や割れた玉は、両方が1回ずつ投げると別の場所にまた現れます。エンドが変わると玉はすべて新しい場所に置かれます。" },
            new[] { "rules.itemkinds.title", "아이템 종류", "Items", "アイテムの種類" },
            new[] { "rules.itemkinds.1.k", "거대 알", "Giant Stone", "ジャイアントストーン" },
            new[] { "rules.itemkinds.1.t", "알이 {giant}배로 커져요. 시트에 있는 동안 계속 커요.", "Your stone grows {giant} times as big, for as long as it stays on the sheet.", "石が{giant}倍の大きさになります。シートにある間ずっと大きいままです。" },
            new[] { "rules.itemkinds.2.k", "미니 알", "Mini Stone", "ミニストーン" },
            new[] { "rules.itemkinds.2.t", "알이 {mini}배로 작아져요. 좁은 틈을 지나가고, 상대가 맞히기 어려워요.", "Your stone shrinks to {mini} times its size: it slips through gaps and is hard to hit.", "石が{mini}倍の小ささになります。狭いすき間を通り抜け、相手に当てられにくくなります。" },
            new[] { "rules.itemkinds.3.k", "폭탄", "Bomb", "ボム" },
            new[] { "rules.itemkinds.4.k", "자석", "Magnet", "マグネット" },
            new[] { "rules.itemkinds.4.t", "알이 움직이는 동안 주변의 알을 끌어당겨 함께 끌고 가요. 멈추면 효과가 끝나요.", "While it moves, it pulls the stones around it and drags them along. Once it stops, it's over.", "動いている間、周りの石を引き寄せて一緒に引っぱっていきます。止まると効果は終わります。" },
            new[] { "rules.itemkinds.5.k", "각도기", "Protractor", "分度器" },
            new[] { "rules.itemkinds.5.t", "조준선이 벽이나 알에 부딪힌 뒤 어디로 가는지 보여줘요. 던질 때까지 내 화면에만 보여요.", "Shows where the aim line goes after it meets a wall or a stone. Only on your screen, until you throw.", "照準線が壁や石に当たった後どこへ行くかを見せます。投げるまで自分の画面にだけ表示されます。" },
            new[] { "rules.itemkinds.3.t", "처음 다른 알에 부딪히는 순간 터져서, 주변의 다른 알을 모두 밀어내요. 알에 부딪히지 못하면 그냥 사라져요.", "It goes off the first time it hits another stone, pushing every other stone nearby away. If it hits none, it fizzles out.", "最初にほかの石にぶつかった瞬間に爆発し、周りのほかの石をすべて押し出します。石に当たらなければ効果は消えます。" },
            new[] { "over.viewResult", "최종 결과 보기", "See the result", "最終結果を見る" },
            new[] { "over.waiting", "응답 기다리는 중…", "Waiting for the server…", "応答を待っています…" },
            new[] { "over.points", "{points}P ({delta})", "{points}P ({delta})", "{points}P（{delta}）" },
            new[] { "over.myWin", "<color=#d9a54c>승리!</color> ({score})", "<color=#d9a54c>Victory!</color> ({score})", "<color=#d9a54c>勝利！</color>（{score}）" },
            new[] { "over.myLoss", "패배! ({score})", "Defeat! ({score})", "敗北！（{score}）" },
            new[] { "over.myDraw", "<color=#d9a54c>무승부</color> ({score})", "<color=#d9a54c>Draw</color> ({score})", "<color=#d9a54c>引き分け</color>（{score}）" },
            new[] { "leaderboard.rank", "순위", "Rank", "順位" },
            new[] { "leaderboard.name", "닉네임", "Name", "名前" },
            new[] { "leaderboard.points", "승점", "Points", "勝ち点" },
            new[] { "leaderboard.winRate", "승률", "Win rate", "勝率" },
            new[] { "leaderboard.mine", "내 순위", "My rank", "自分の順位" },
            new[] { "leaderboard.unranked", "아직 순위가 없어요", "No rank yet", "まだ順位がありません" },
            new[] { "leaderboard.guest", "구글 로그인하면 순위에 올라가요", "Sign in with Google to get ranked", "Googleでログインするとランキングに載ります" },
            new[] { "leaderboard.empty", "아직 순위에 오른 플레이어가 없어요", "No one is ranked yet", "まだランキングに誰もいません" },
            new[] { "leaderboard.loading", "불러오는 중…", "Loading…", "読み込み中…" },
            new[] { "leaderboard.failed", "순위를 불러오지 못했어요", "Could not load the rankings", "ランキングを読み込めませんでした" },
            new[] { "out.hog", "최소 라인을 넘지 못해 무효", "Short of the min line: no stone", "最小ラインを越えられず無効" },
            new[] { "out.back", "아웃 라인을 넘어가 무효", "Past the out line: no stone", "アウトラインを越えて無効" },
            new[] { "out.near", "시트 아래로 나가 무효", "Off the near end: no stone", "手前に出て無効" },
            new[] { "out.knocked", "{team} {n}개 아웃", "{team} {n} out", "{team} {n}個アウト" },
            new[] { "shot.takeout", "테이크아웃!", "Takeout!", "テイクアウト！" },
            new[] { "shot.takeout2", "더블 테이크아웃!", "Double Takeout!", "ダブルテイクアウト！" },
            new[] { "shot.takeout3", "트리플 테이크아웃!", "Triple Takeout!", "トリプルテイクアウト！" },
            new[] { "timeout.title", "시간 초과", "Time's up", "時間切れ" },
            new[] { "timeout.body", "{name} 알을 잃었습니다", "{name} loses this stone", "{name}はこの石を失いました" },
            new[] { "timeout.lsd", "기록 없이 넘어갑니다", "No record for this draw", "記録なしで次へ" },
            new[] { "foul.lost",
                "이번 엔드는 더이상 쿠션이 불가능합니다.\n{team} 알을 잃었습니다.",
                "No more cushions this end.\n{team} loses this stone.",
                "このエンドはもうクッションできません。\n{team}の石を失いました。" },

            // ---- on the sheet ----
